{"implementation":"import math


def solve(case):
    """Compute mutual-reachability weights and a deterministic MST."""
    payload = case.get("payload", case) if isinstance(case, dict) else None
    if not isinstance(payload, dict):
        raise ValueError("case must be an object or contain a payload object")

    for key in ("nodes", "core_distance", "distances"):
        if key not in payload:
            raise ValueError("missing required field: " + key)

    nodes = payload["nodes"]
    core = payload["core_distance"]
    distances = payload["distances"]

    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(core, dict):
        raise ValueError("core_distance must be an object")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    seen = set()
    node_list = []
    for node in nodes:
        if not isinstance(node, str):
            raise ValueError("node ids must be strings")
        if node in seen:
            raise ValueError("duplicate node id: " + node)
        seen.add(node)
        node_list.append(node)

    node_set = set(node_list)
    core_out = {}
    for node in node_list:
        if node not in core:
            raise ValueError("missing core distance for node: " + node)
        value = core[node]
        if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(value):
            raise ValueError("invalid core distance for node: " + node)
        value = float(value)
        if value < 0.0:
            raise ValueError("core distances must be non-negative")
        core_out[node] = value

    extra_core = set(core.keys()) - node_set
    if extra_core:
        raise ValueError("core_distance contains unknown node: " + sorted(extra_core)[0])

    edge_by_pair = {}
    for item in distances:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("each distance entry must be a triple")
        a, b, distance = item
        if not isinstance(a, str) or not isinstance(b, str):
            raise ValueError("distance endpoints must be strings")
        if a not in node_set or b not in node_set:
            raise ValueError("distance endpoint is not registered")
        if a == b:
            raise ValueError("self distances are not valid edges")
        if not isinstance(distance, (int, float)) or isinstance(distance, bool) or not math.isfinite(distance):
            raise ValueError("invalid distance value")
        distance = float(distance)
        if distance < 0.0:
            raise ValueError("distances must be non-negative")
        u, v = (a, b) if a <= b else (b, a)
        pair = (u, v)
        if pair in edge_by_pair:
            if edge_by_pair[pair] != distance:
                raise ValueError("conflicting duplicate distance for edge")
            continue
        reachability = max(core_out[u], core_out[v], distance)
        edge_by_pair[pair] = distance

    edges = []
    for (u, v), distance in edge_by_pair.items():
        edges.append({
            "left": u,
            "right": v,
            "distance": distance,
            "weight": max(core_out[u], core_out[v], distance),
        })
    edges.sort(key=lambda edge: (edge["weight"], edge["left"], edge["right"]))

    parent = {node: node for node in node_list}
    rank = {node: 0 for node in node_list}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb] or (rank[ra] == rank[rb] and rb < ra):
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    mst = []
    total = 0.0
    needed = max(0, len(node_list) - 1)
    for edge in edges:
        if union(edge["left"], edge["right"]):
            chosen = dict(edge)
            mst.append(chosen)
            total += chosen["weight"]
            if len(mst) == needed:
                break

    if len(mst) != needed:
        raise ValueError("distance graph is disconnected")

    return {
        "nodes": list(node_list),
        "core_distance": core_out,
        "mutual_reachability": edges,
        "mst": mst,
        "total_weight": total,
    }
"}
